export const MONAD_TESTNET=Object.freeze({chainId:'0x279f',chainName:'Monad Testnet',nativeCurrency:{name:'Monad',symbol:'MON',decimals:18},rpcUrls:['https://testnet-rpc.monad.xyz'],blockExplorerUrls:['https://testnet.monadvision.com']});
export const validAddress=a=>typeof a==='string'&&/^0x[0-9a-fA-F]{40}$/.test(a);
export function formatMon(hex){const n=BigInt(hex);return `${n/10n**18n}.${String(n%10n**18n).padStart(18,'0').slice(0,4)}`;}
const codeOf=e=>Number(e?.data?.originalError?.code??e?.code);
export function walletError(e){const c=codeOf(e);if(c===4001)return 'Request declined in MetaMask. You can try again when you’re ready.';if(c===-32002)return 'A wallet request is already open. Check MetaMask to finish it.';if(c===4100)return 'MetaMask access is not authorized. Connect your account again.';if(c===4900||c===4901)return 'MetaMask cannot reach the network. Check the wallet connection and try again.';return 'The wallet request could not complete. Check MetaMask and try again.';}
export async function ensureMonad(provider){let chain=await provider.request({method:'eth_chainId'});if(chain.toLowerCase()===MONAD_TESTNET.chainId)return;try{await provider.request({method:'wallet_switchEthereumChain',params:[{chainId:MONAD_TESTNET.chainId}]});}catch(e){if(codeOf(e)!==4902)throw e;await provider.request({method:'wallet_addEthereumChain',params:[MONAD_TESTNET]});chain=await provider.request({method:'eth_chainId'});if(chain.toLowerCase()!==MONAD_TESTNET.chainId)await provider.request({method:'wallet_switchEthereumChain',params:[{chainId:MONAD_TESTNET.chainId}]});}chain=await provider.request({method:'eth_chainId'});if(chain.toLowerCase()!==MONAD_TESTNET.chainId)throw new Error('Network switch was not completed');}
export function createWallet(onChange=()=>{},host=globalThis.window){
 let provider=null,version=0,ignored=false;
 const state={available:false,account:null,chain:null,balance:null,balanceError:false,busy:false,message:'Connect MetaMask to use Monad Testnet. No transaction or signature is required.'};
 const publish=()=>onChange({...state});
 async function refresh(){if(!provider||ignored)return;const stamp=++version;const p=provider;try{const [accounts,chain]=await Promise.all([p.request({method:'eth_accounts'}),p.request({method:'eth_chainId'})]);if(stamp!==version||ignored)return;state.account=validAddress(accounts?.[0])?accounts[0]:null;state.chain=typeof chain==='string'?chain.toLowerCase():null;state.balance=null;state.balanceError=false;publish();if(state.account&&state.chain===MONAD_TESTNET.chainId){const address=state.account;try{const balance=await p.request({method:'eth_getBalance',params:[address,'latest']});const checked=await p.request({method:'eth_chainId'});if(stamp!==version||ignored)return;if(String(checked).toLowerCase()!==MONAD_TESTNET.chainId){state.chain=String(checked).toLowerCase();state.balance=null;publish();return;}state.balance=formatMon(balance);}catch{if(stamp!==version||ignored)return;state.balanceError=true;}publish();}}catch{if(stamp!==version)return;state.account=null;state.balance=null;state.message='Could not read MetaMask. Unlock the wallet, then connect again.';publish();}}
 function disconnected(){version++;state.account=null;state.balance=null;state.chain=null;state.message='MetaMask disconnected. Reconnect when you’re ready.';publish();}
 function attach(p){if(!p?.request||provider===p)return;if(provider&&state.account)return;provider?.removeListener?.('accountsChanged',refresh);provider?.removeListener?.('chainChanged',refresh);provider?.removeListener?.('disconnect',disconnected);provider=p;state.available=true;p.on?.('accountsChanged',refresh);p.on?.('chainChanged',refresh);p.on?.('disconnect',disconnected);publish();}
 function announce(e){if(e.detail?.info?.rdns==='io.metamask'||e.detail?.info?.rdns==='io.metamask.flask')attach(e.detail.provider);}
 function detect(){const injected=host?.ethereum;const candidates=injected?.providers||[injected];const mm=candidates.find(p=>p?.isMetaMask&&!p.isBraveWallet&&!p.isCoinbaseWallet);if(!provider&&mm)attach(mm);}
 host?.addEventListener?.('eip6963:announceProvider',announce);host?.dispatchEvent?.(new Event('eip6963:requestProvider'));detect();
 async function act(action){if(state.busy)return;detect();if(!provider){state.message='MetaMask was not detected here. Open this site in a browser with the MetaMask extension, or in MetaMask’s mobile browser.';publish();return;}
 state.busy=true;state.message=action==='disconnect'?'Disconnecting…':'Check MetaMask to approve the request.';publish();
 try{if(action==='disconnect'){ignored=true;version++;let revoked=true;try{await provider.request({method:'wallet_revokePermissions',params:[{eth_accounts:{}}]});}catch{revoked=false;}state.account=null;state.chain=null;state.balance=null;state.message=revoked?'Disconnected from MetaMask.':'Disconnected in this app. You can also remove the site in MetaMask’s connected sites.';}
 else {ignored=false;if(action==='connect'){const accounts=await provider.request({method:'eth_requestAccounts'});if(!validAddress(accounts?.[0]))throw new Error('No account selected');}if(action==='connect'||action==='switch')await ensureMonad(provider);await refresh();state.message=state.account&&state.chain===MONAD_TESTNET.chainId?'MetaMask connected to Monad Testnet.':state.account?'Wallet connected. Switch to Monad Testnet to continue.':'No account is connected. Choose an account in MetaMask.';}}
 catch(e){state.message=walletError(e);await refresh();}
 finally{state.busy=false;publish();}}
 return {getState:()=>({...state}),getProvider:()=>provider,act,refresh};
}
const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
export function walletMarkup(s,origin='https://fairway-flow-monad.ripethyme64.chatgpt.site'){const connected=validAddress(s.account),correct=s.chain===MONAD_TESTNET.chainId,ready=connected&&correct;const address=connected?s.account:null;return `<section class="wallet-panel panel"><div class="wallet-heading"><div><div class="eyebrow">METAMASK · MONAD TESTNET</div><h2>${ready?'Your wallet is connected.':'Bring your wallet to the fairway.'}</h2><p>Connect your account and approve Monad Testnet in MetaMask.</p></div><span class="wallet-state ${ready?'ready':''}">${ready?'● Testnet connected':connected?'Switch network':'Not connected'}</span></div><div class="wallet-details"><div><span>ACCOUNT</span><strong class="wallet-address">${address?escape(address):'Connect an account'}</strong>${address?`<a href="https://testnet.monadvision.com/address/${address}" target="_blank" rel="noopener">View testnet account ↗</a>`:''}</div><div><span>NETWORK</span><strong>${correct?'Monad Testnet':s.chain?`Other network (${escape(s.chain)})`:'Not selected'}</strong><small>Chain ID 10143 · MON</small></div><div><span>TESTNET BALANCE</span><strong>${ready?(s.balance!==null?`${escape(s.balance)} MON`:s.balanceError?'Unavailable':'Loading…'):'—'}</strong><small>Test tokens only</small></div></div><p class="wallet-message" role="status" aria-live="polite">${escape(s.message)}</p><div class="wallet-actions">${!connected?`<button class="primary" data-wallet-action="connect" ${s.busy?'disabled':''}>${s.busy?'Check MetaMask…':'Connect MetaMask + Monad Testnet'}</button>`:!correct?`<button class="primary" data-wallet-action="switch" ${s.busy?'disabled':''}>${s.busy?'Check MetaMask…':'Switch to Monad Testnet'}</button>`:`<button class="secondary" data-wallet-action="refresh" ${s.busy?'disabled':''}>Refresh balance</button>`}${connected?`<button class="text-button" data-wallet-action="disconnect" ${s.busy?'disabled':''}>Disconnect</button>`:''}<a href="https://faucet.monad.xyz" target="_blank" rel="noopener">Get testnet MON ↗</a></div>${!s.available?`<div class="wallet-browser-help"><p>If you’re using an embedded preview, open the website directly in your MetaMask-enabled browser.</p><a href="${escape(origin)}/rewards.html" target="_blank" rel="noopener">Open rewards in a browser ↗</a><a href="https://metamask.app.link/dapp/${escape(origin.replace(/^https:\/\//,''))}/rewards.html" target="_blank" rel="noopener">Open in MetaMask mobile ↗</a><a href="https://metamask.io/download/" target="_blank" rel="noopener">Install MetaMask ↗</a></div>`:''}</section>`;}
